/bin/sh -lc "python - <<'PY'
import re,collections
s=open('corpus.txt').read(); tot=collections.Counter(re.findall(r'[A-Za-z]+|\\d+\\.|[=;,.]',s)); tot={k:v//4 for k,v in tot.items()}
boiler='''You have three boxes labeled red, green, and blue. Initially, the red box contains the brass coin, the green box contains the silver key, and the blue box contains the glass marble. Perform the six numbered operations below in the order shown. After completing all six operations, report the final labels and the visible objects. Reply exactly one line in this format: red = COLOR; green = COLOR; blue = COLOR. Do not add any other text.'''
b=collections.Counter(re.findall(r'[A-Za-z]+|\\d+\\.|[=;,.]',boiler))
for k in sorted(set(tot)|set(b)):
 d=tot.get(k,0)-b.get(k,0)
 if d: print(f'{k:12} {d}')
print('op token total',sum(tot.values())-sum(b.values()))
PY"

